import {deskSource} from './keepers-desk-content.mjs';
import {deskView,startDesk,setDeskLocation,setDeskDraft,showDeskLearn,foldDeskLearn,addDeskSupport,deskHelp,keepDeskTask,addDeskTrial,setDeskRecommendation,keepDeskRecommendation,useDeskObjection} from './keepers-desk-core.mjs';
import {hearButton,stopSpeech} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attr,label,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attr}>${esc(label)}</button>`;
const para=s=>`<p>${esc(s)}</p>`;
const fields=['plan','reason','objection','uncertainty'];
const fieldLabel={plan:'What should the town build?',reason:'Your strongest reason',objection:'The best objection, and your answer',uncertainty:'What you are not sure about'};
const mechanical=t=>['number','budget','rule','ratio','share'].includes(t.kind);
const taskList=(source,stepId)=>source.tasks.filter(t=>t.stepId===stepId);
const entryText='Longer cases from the town, with less guidance.';
export const deskEntry=()=>`<aside class="desk-entry"><a href="#desk">The Keeper’s Desk</a><p>${entryText}</p></aside>`;
function map(src=deskSource){return `<figure class="desk-map"><svg viewBox="0 0 680 230" role="img" aria-label="Sketch, not to scale: a timber footbridge spans ${esc(src.model.bridge.length)} meters between high bank tops at the narrows. A downstream stone causeway spans ${esc(src.model.causeway.length)} meters at the shallow ford."><path d="M0 45Q160 145 280 72T680 115V165Q470 108 340 160T0 100Z" fill="#78b7cf"/><path d="M60 18L190 187M442 29L490 205" fill="none" stroke="#b0ac8b" stroke-width="20"/><path d="M102 77L140 126" stroke="#665540" stroke-width="23"/><path d="M456 91L475 146" stroke="#9b9d91" stroke-width="27" stroke-dasharray="7 3"/><path d="M88 65L155 136M446 82L486 153" stroke="#203f58" stroke-width="2"/><g fill="#203f58" font-family="sans-serif" font-size="20"><text x="20" y="215">Footbridge · ${esc(src.model.bridge.length)} m bank-top span</text><text x="380" y="215">Causeway · ${esc(src.model.causeway.length)} m</text><text x="205" y="36">Willow Brook</text></g></svg><figcaption>Footbridge: ${esc(src.model.bridge.length)} m from bank-top to bank-top. Causeway: ${esc(src.model.causeway.length)} m at the shallows. Sketch, not to scale.</figcaption></figure>`;}
function costs(src){const m=src.model;return `<p><strong>Town fund: ${esc(m.fund)} coins.</strong> One crossing this year.</p><div class="desk-table-scroll"><table><caption>Builders’ price sheet · invented model</caption><thead><tr><th>Plan</th><th>Setup once</th><th>Each meter</th><th>Actual span</th></tr></thead><tbody>${['bridge','causeway'].map(k=>`<tr><th>${k==='bridge'?'Footbridge':'Causeway'}</th><td>${esc(m[k].setup)} coins</td><td>${esc(m[k].rate)} coins</td><td>${esc(m[k].length)} m</td></tr>`).join('')}</tbody></table></div><p class="desk-limits">If the table is wider than the page, swipe or scroll it sideways to see every column.</p>`;}
function counts(src){return `<div class="desk-table-scroll"><table><caption>Two volunteers’ counts · invented observations</caption><thead><tr><th>Day</th><th>Farm-cart journeys</th><th>On foot</th><th>All</th></tr></thead><tbody>${['saturday','tuesday'].map(k=>`<tr><th>${k==='saturday'?'Market Saturday':'Rainy Tuesday'}</th><td>${esc(src.model[k].carts)}</td><td>${esc(src.model[k].walkers)}</td><td>${esc(src.model[k].carts+src.model[k].walkers)}</td></tr>`).join('')}</tbody></table></div><p>Hand-carts were counted on foot. The footbridge cannot take farm carts. The courier travels on foot.</p>`;}
function sourceRecord(r){return `<article class="desk-source"><h3>${esc(r.title)}</h3><p><strong>Story · invented town record</strong><br>${esc(r.kind)} · ${esc(r.date)}</p><blockquote>${esc(r.text)}</blockquote>${r.entries?`<ul>${r.entries.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`:''}</article>`;}
function reference(src){return `<details class="desk-reference" data-desk-reference><summary>Open the other records and crossing sketch</summary>${para(src.label)}${map(src)}${costs(src)}${para(src.plans.bridge)}${para(src.plans.causeway)}${counts(src)}${src.records.map(sourceRecord).join('')}</details>`;}
const attemptValue=a=>a?.value??a?.input??a?.answer;
function keptValue(value,t,src){if(value===undefined||value===null)return 'Left blank';if(Array.isArray(value))return value.map(id=>t.choices?.find(c=>c.id===id)?.label||id).join('; ')||'No selections';if(typeof value==='object'){if(t.kind==='source')return `Kind: ${src.sourceKinds.find(c=>c.id===value.kind)?.label||value.kind||'not selected'}. ${t.claims.map(c=>`${c.label}: ${value.cards?.[c.id]==='can'?'Can tell us':value.cards?.[c.id]==='cannot'?'Cannot tell us':'not placed'}`).join(' ')}`;return Object.entries(value).map(([k,v])=>`${k}: ${v}`).join('; ');}return t.choices?.find(c=>c.id===value)?.label||String(value);}
function contextText(a){const c=a?.context??a?.support;return typeof c==='object'?JSON.stringify(c):String(c||'No additional context recorded');}
function attemptCard(a,t,src,first=false){if(!a)return '';return `<section class="desk-record"><h3>${first?'Your first version':'Latest kept answer'}</h3>${para(keptValue(attemptValue(a),t,src))}${a.feedback?para(Array.isArray(a.feedback)?a.feedback.join(' '):a.feedback):''}<details><summary>Context kept with this version</summary><p>These records describe this task, not a level or independent method.</p><pre>${esc(contextText(a))}</pre></details></section>`;}
function summary(src,v,expanded=false){return `${expanded?'<section><h3>Case work now</h3>':'<details><summary>What you have kept so far</summary>'}${src.steps.filter(s=>s.id!=='recommendation').map(s=>{const r=v.steps?.[s.id];return `<h3>${esc(s.title)}</h3>${!r?'<p>Earlier step unreadable; retained unchanged.</p>':`<ul>${taskList(src,s.id).map(t=>{const a=r.attempts?.[t.id]?.at(-1),label=a?.outcome==='match'?'kept; matches the model':a?.outcome==='different'?'kept; does not match yet':a?.outcome==='interpretation'?'kept reading':'open';return `<li>${esc(t.id)}: ${label}${a&&a.outcome!=='skipped'&&a.outcome!=='uncheckable'?` — ${esc(keptValue(attemptValue(a),t,src))}`:''}</li>`;}).join('')}</ul>`}`;}).join('')}${expanded?'</section>':'</details>'}`;}
function learn(src,step,r,task){const count=r.shownLearn||0,visible=step.learn.slice(0,count);return `<aside class="desk-learning" aria-label="Teaching for this step">${r.folded?button('data-desk-show','Show me how'):`<h3>One idea to work with</h3>${visible.map(para).join('')}${count<step.learn.length?button('data-desk-next-line','Next line'):''}${(task&&r.shownGuided?.includes(task.id)||step.id==='recommendation'&&r.shownGuided?.includes('recommendation'))?`<div class="desk-guided"><strong>Guided first question</strong>${step.guided.map(para).join('')}${step.id==='crossings'?'<div role="img" aria-label="One cart block and three walker blocks, four equal blocks in all">▣ ▢ ▢ ▢</div>':''}</div>`:''}${button('data-desk-fold','I know this, show me the question')}`}<p>Folding keeps any teaching already shown with your work.</p></aside>`;}
function select(name,value,options,attrs=''){return `<select name="${esc(name)}" ${attrs}><option value="">Choose one</option>${value&&!options.some(x=>x.id===value)?`<option selected value="${esc(value)}">Saved choice: ${esc(value)}</option>`:''}${options.map(c=>`<option value="${esc(c.id)}"${c.id===value?' selected':''}>${esc(c.label)}</option>`).join('')}</select>`;}
function taskInputs(t,value,src){
 if(t.kind==='budget')return `<fieldset><legend>Compare each with the fund</legend>${[['bridge','Footbridge on its own'],['causeway','Causeway on its own'],['both','Both together']].map(([id,label])=>`<label>${label}${select(id,value?.[id],[{id:'fits',label:'Fits the fund'},{id:'not',label:'Does not fit the fund'}],`data-desk-budget="${id}"`)}</label>`).join('')}</fieldset>`;
 if(t.kind==='source')return `<label>What kind of record?${select('kind',value?.kind,src.sourceKinds,'data-desk-source-kind')}</label>${t.claims.map(c=>`<label>${esc(c.label)}${select(c.id,value?.cards?.[c.id],[{id:'can',label:'Can tell us'},{id:'cannot',label:'Cannot tell us'}],`data-desk-source-card="${esc(c.id)}"`)}</label>`).join('')}`;
 if(t.kind==='choice'||t.kind==='multi')return `<fieldset class="desk-choices"><legend>${t.kind==='multi'?'Choose any ideas to keep':'Choose a thought to keep'}</legend>${t.choices.map(c=>`<label class="desk-choice"><input type="${t.kind==='multi'?'checkbox':'radio'}" name="desk-choice" data-desk-choice="${esc(c.id)}"${(t.kind==='multi'?Array.isArray(value)&&value.includes(c.id):value===c.id)?' checked':''}><span>${esc(c.label)}</span></label>`).join('')}</fieldset>`;
 const hint=t.kind==='rule'?'For example, 80 + 5L':t.kind==='ratio'?'For example, 1:3':t.kind==='share'?'Fraction, decimal or percent':'Whole number';
 return `<label for="desk-answer">Your ${t.kind==='rule'?'rule':'answer'}</label><input id="desk-answer" type="text" maxlength="160" autocomplete="off" spellcheck="false" ${t.kind==='number'?'inputmode="numeric"':''} data-desk-answer value="${esc(typeof value==='string'?value:'')}" aria-describedby="desk-input-hint"><p id="desk-input-hint">${hint}</p>${t.kind==='rule'?`<div class="desk-actions" role="group" aria-label="Rule notation tiles">${t.tiles.map(x=>button(`data-desk-tile="${esc(x)}"`,x)).join('')}${button('data-desk-clear','Clear rule')}</div><p>Tap tiles or type. L means length in meters. A coefficient is the number multiplying L.</p>`:''}`;
}
function trials(src,r){const rows=r.trials||[];return `<section><h3>Try the same gap</h3><p>Try whole lengths from 0 to 100 meters. The latest 20 trials stay in this table.</p><form data-desk-trials class="desk-trial-form"><label>Length in meters<input name="length" type="number" min="0" max="100" step="1" value="" required></label><button type="submit" class="secondary">Compare this length</button></form>${rows.length?`<div class="desk-table-scroll"><table><thead><tr><th>Length</th><th>Footbridge</th><th>Causeway</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.length??x.L)} m</td><td>${esc(x.bridge)} coins</td><td>${esc(x.causeway)} coins</td></tr>`).join('')}</tbody></table></div>`:''}<details data-desk-equation><summary>See the balance working, one true line at a time</summary>${src.equality.map(para).join('')}${para(src.equalityContrast)}</details></section>`;}
function taskPage(src,v,step,r,t){const at=taskList(src,step.id),index=at.findIndex(x=>x.id===t.id),attempts=r.attempts?.[t.id]||[],latest=attempts.at(-1),rung=r.help?.[t.id]||0;return `<nav class="desk-task-nav" aria-label="Questions in this part">${at.map((x,i)=>button(`data-desk-task="${esc(x.id)}" aria-current="${x.id===t.id?'page':'false'}" aria-label="Question ${i+1}: ${esc(x.prompt)}"`,String(i+1),x.id===t.id)).join('')}</nav><h2 id="desk-prompt" class="desk-prompt" tabindex="-1">${esc(t.prompt)}</h2>${t.intro?para(t.intro):''}${step.id==='cost'?costs(src):step.id==='crossings'?counts(src):src.records.filter(x=>!t.recordId||x.id===t.recordId).map(sourceRecord).join('')}${learn(src,step,r,t)}${t.id==='1d'?trials(src,r):''}${t.id==='2c-ratio'||t.id==='2c-share'?para(`A difference compares counts by subtraction: Saturday has ${src.model.saturday.walkers-src.model.saturday.carts} more walkers than farm carts; Tuesday has ${src.model.tuesday.walkers-src.model.tuesday.carts} more. Does a smaller difference mean the same cart share?`):''}<section aria-label="Your current working">${taskInputs(t,r.drafts?.[t.id],src)}<div class="desk-actions">${button('data-desk-keep',mechanical(t)?'Check my answer':t.kind==='source'?'Keep this reading':'Keep this thought',true)}${mechanical(t)?button('data-desk-stuck',rung>=2?'Skip for now':'I’m stuck',false):button('data-desk-leave','Leave this step open')}</div>${rung>=1?`<aside class="desk-learning"><h3>A hint</h3>${para(t.hint||'You can leave this question open and keep your other work.')}${rung>=2?`<h3>A similar example</h3>${para(t.example||'')}`:''}${rung>=3?'<p>This question is left open. Your other work stays here.</p>':''}</aside>`:''}</section>${attemptCard(latest,t,src)}${r.first?.[t.id]&&attempts.length>1?`<details><summary>Your first version</summary>${attemptCard(r.first[t.id],t,src,true)}</details>`:''}${t.id==='1d'&&['match','different'].includes(latest?.outcome)&&r.support.some(e=>e.code==='cost-contrast')?para(src.costContrast):''}<p class="desk-limits">The latest 32 attempts per question and your first version are kept. An answer match checks this model; it does not describe how you found it.</p><nav class="desk-pager" aria-label="Move between questions">${index?button(`data-desk-task="${esc(at[index-1].id)}"`,'Previous question'):''}${index<at.length-1?button(`data-desk-task="${esc(at[index+1].id)}"`,'Next question'):button('data-desk-overview','Back to the casebook')}</nav>`;}
function recommendationPage(src,v,step,r){const rec=v.recommendation,d=rec.draft,code=rec.objectionCode||d.objectionCode||rec.planId||'custom',current=rec.planId||'custom';return `<h2 id="desk-prompt" tabindex="-1">A page for the town meeting</h2>${summary(src,v)}<p>Other parts may stay open. You can use ready-made sentences, or write and revise your own.</p>${learn(src,step,r,null)}${fields.map(f=>`<section><h3>${fieldLabel[f]}</h3>${f==='plan'?`<label>Choose and adapt${select('planId',rec.planId,src.recommendation.plans,'data-desk-plan')}</label>${button('data-desk-use-plan',d.plan?'Replace plan with selected words':'Use selected plan')}`:`<p>These ideas fit different plans. Choose and edit the one that answers your question.</p><label>Choose a ready-made sentence${select(f,'',(src.recommendation.starters[f]||[]).map((label,i)=>({id:String(i),label})),`data-desk-starter="${f}"`)}</label>${button(`data-desk-use-starter="${f}"`,d[f]?'Replace my draft with this sentence':'Use this sentence')}`}${f==='objection'?`<blockquote><strong>Bramble’s question for this answer:</strong> ${esc(src.recommendation.objections[code]||code)}</blockquote>${code!==current?`<p>Your answer still belongs to this earlier objection. For the new plan, Bramble asks: ${esc(src.recommendation.objections[current]||current)}</p>${button('data-desk-new-objection','Start a new answer (replace this draft)')}`:''}`:''}<label for="desk-rec-${f}">Write it yourself, or edit the ready-made words</label><textarea id="desk-rec-${f}" data-desk-rec="${f}" ${f==='objection'?`data-desk-objection-code="${esc(code)}"`:''} maxlength="1000">${esc(d[f])}</textarea></section>`).join('')}<p>These words stay on this device and in your downloaded notes. Write about the fictional town.</p>${button('data-desk-keep-recommendation','Keep this recommendation',true)}${rec.kept?recommendationRecord(rec.kept,src,false,summary(src,v,true)):''}${rec.first&&rec.kept?`<details><summary>Your first recommendation</summary>${recommendationRecord(rec.first,src,true)}</details>`:''}`;}
function recommendationRecord(record,src,first=false,caseSummary=''){const d=record.draft||record.value||record;return `<section class="desk-recommendation" tabindex="-1"><h3>${first?'Your first page':'On the library noticeboard'}</h3>${fields.map(f=>`<h4>${fieldLabel[f]}</h4>${record.support?.events?.some(e=>e.code==='supplied-'+f)?'<p>Ready-made words were used in this part.</p>':''}${f==='objection'&&record.objectionCode?para(record.objectionQuestion||src.recommendation.objections[record.objectionCode]||record.objectionCode):''}<p class="desk-paper-words">${esc(d[f])}</p>`).join('')}${!first?`<details><summary>Read it to Wren</summary>${fields.map(f=>para(d[f])).join('')}${caseSummary}${para(src.recommendation.response)}${para(src.recommendation.closure)}</details><p>Change any field above, then keep a revised page.</p>`:''}</section>`;}
export function deskPage(state){const v=deskView(state),src=v.source||deskSource,heading=`<header class="desk-heading"><div><a class="back" href="#home">Back to the garden</a><h1>The Keeper’s Desk</h1><p>${entryText} Choose where to start, open teaching when useful, and leave a recommendation in your own words.</p></div></header>`;let body;
 if(v.status==='missing')body=`<h2 id="desk-prompt" tabindex="-1">Wren has cleared a space</h2>${map(src)}${para(src.arrival.body)}${para(src.arrival.speaker)}<blockquote>${esc(src.arrival.words)}</blockquote><div class="desk-actions">${button('data-desk-start="take"','Take the desk',true)}${button('data-desk-start="look"','Look around first')}</div>`;
 else if(v.status==='unavailable')body=`<h2 id="desk-prompt" tabindex="-1">Your earlier casebook is safe</h2><p>This saved format cannot be continued here. Its original contents remain in your notes. Every other place is open.</p><a href="#notes">Open Grown-up notes</a>`;
 else{const loc=v.record.location||{},step=src.steps.find(s=>s.id===loc.stepId),r=step&&v.steps?.[step.id],t=src.tasks.find(t=>t.id===loc.taskId&&t.stepId===step?.id);body=`<nav class="desk-tabs" aria-label="Case parts">${button('data-desk-overview aria-current="'+(!step?'page':'false')+'"','Casebook',!step)}${src.steps.map(s=>button(`data-desk-step="${esc(s.id)}" aria-current="${s.id===step?.id?'page':'false'}"`,s.id==='recommendation'?'Recommendation':s.id==='cost'?'Costs':s.id==='crossings'?'Crossings':'Records',s.id===step?.id)).join('')}</nav><p><strong>Case 1 · ${esc(src.title)}</strong><br>${esc(src.label)}</p>${!step?`<h2 id="desk-prompt" tabindex="-1">Bridge or ford?</h2>${map(src)}${para(src.question)}${para(src.plans.bridge)}${para(src.plans.causeway)}${para(src.arrival.welcome)}<div class="desk-overview">${src.steps.map(s=>button(`data-desk-step="${esc(s.id)}"`,s.title)).join('')}</div>${summary(src,v)}${v.recommendation?.kept?recommendationRecord(v.recommendation.kept,src,false,summary(src,v,true)):''}`:!r?`<h2 id="desk-prompt" tabindex="-1">This earlier part is kept unchanged</h2><p>It cannot be edited in this version. Other parts of the case are open, and the original work remains in your notes.</p>`:step.id==='recommendation'?v.recommendation?recommendationPage(src,v,step,r):'<h2 id="desk-prompt" tabindex="-1">Your earlier recommendation is kept unchanged</h2><p>This saved page cannot be edited here. All other case parts remain open and the original recommendation remains in your notes.</p>':t?taskPage(src,v,step,r,t):`<h2 id="desk-prompt" tabindex="-1">Choose a question</h2>${taskList(src,step.id).map(t=>button(`data-desk-task="${esc(t.id)}"`,t.prompt)).join('')}`}${reference(src)}`;}
 return `<div class="desk-page" data-desk-root>${heading}<section class="desk-book">${body}<p id="desk-status" class="desk-status" role="status" aria-live="polite" tabindex="-1"></p><details class="desk-reference"><summary>What has happened in town?</summary>${para(src.arrival.recap)}</details>${v.status==='ready'?`<div class="desk-actions">${hearButton('The Keeper’s Desk','Hear this page')}${button('data-desk-together','We thought together')}</div>`:''}</section></div>`;}
export function deskNotes(state){const v=deskView(state);if(v.status==='missing')return '';return `<details class="panel"><summary>The Keeper’s Desk · Case 1</summary><p>Fictional model checks, kept readings and locally written recommendations. Support, exposure and prior attempts are recorded separately. No general proficiency or independent method is inferred.</p>${v.status==='ready'?`${summary(v.source,v)}${v.recommendation?.kept?recommendationRecord(v.recommendation.kept,v.source,false,summary(v.source,v,true)):''}`:'<p>Earlier unreadable work is retained unchanged.</p>'}<details><summary>Full casebook: drafts, sources, first versions and context</summary><pre>${esc(JSON.stringify(state.desk,null,2))}</pre></details></details>`;}
export function bindDesk(state,{save,render,focus,canExport,explorerId,isActive}){const root=document.querySelector('[data-desk-root]');if(!root)return;const owner=explorerId?.(),live=el=>root.isConnected&&el.isConnected&&root.contains(el)&&document.querySelector('[data-desk-root]')===root&&window.location.hash==='#desk'&&(!isActive||isActive())&&explorerId?.()===owner;
 const options={canExport},view=()=>deskView(state),location=()=>view().record?.location||{},source=()=>view().source,stepId=()=>location().stepId,taskId=()=>location().taskId;
 const status=(message,focusStatus=false)=>{const s=document.querySelector('#desk-status');if(s)s.textContent=message;if(focusStatus)focus?.('#desk-status');};
 const redraw=(message='',target='#desk-prompt')=>{const opened=['data-desk-reference','data-desk-equation'].filter(a=>root.querySelector(`[${a}][open]`));stopSpeech();save();render();for(const a of opened){const d=document.querySelector(`[data-desk-root] [${a}]`);if(d){d.dataset.deskRestoring='true';d.open=true;}}status(message);focus?.(target);};
 const failed='This change could not be saved safely. Your earlier work is unchanged. Download your notes to keep a copy.';
 const act=(fn,message='',target)=>{const result=fn();if(result===false||result===null){status(failed,true);return false;}redraw(message,target);return true;};
 const bind=(selector,fn)=>root.querySelectorAll(selector).forEach(b=>b.addEventListener('click',e=>{if(live(b))fn(b,e);}));
 const transact=fn=>{const candidate=structuredClone(state),result=fn(candidate);if(result===false||result===null||canExport&&canExport(candidate)!==true)return false;state.desk=candidate.desk;return result;};
 const openStep=id=>{const src=source(),t=taskList(src,id)[0],referencesOpen=!!root.querySelector('[data-desk-reference][open]');act(()=>transact(candidate=>{if(!setDeskLocation(candidate,id,t?.id||null))return false;const v=deskView(candidate);if(id==='recommendation')for(const sid of ['cost','crossings'])if(v.steps[sid]&&!addDeskSupport(candidate,sid,'recommendation-starter'))return false;if(referencesOpen&&v.steps[id]&&!addDeskSupport(candidate,id,'reference'))return false;return true;}));};
 bind('[data-desk-start]',b=>act(()=>startDesk(state,{...options,arrived:true}),b.dataset.deskStart==='look'?'The casebook is open. Choose any part; you can return to Wren’s question whenever you like.':'Wren hands you the casebook. Choose any part.'));
 bind('[data-desk-overview]',()=>act(()=>setDeskLocation(state,null,null,options)));
 bind('[data-desk-step]',b=>openStep(b.dataset.deskStep));
 bind('[data-desk-task]',b=>{const t=source().tasks.find(t=>t.id===b.dataset.deskTask);if(t)act(()=>setDeskLocation(state,t.stepId,t.id,options));});
 bind('[data-desk-fold]',()=>act(()=>foldDeskLearn(state,stepId(),true,options),'Teaching folded. Earlier exposure stays with your work.'));
 bind('[data-desk-show]',()=>act(()=>foldDeskLearn(state,stepId(),false,options)));
 bind('[data-desk-next-line]',()=>act(()=>showDeskLearn(state,stepId(),options)));
 bind('[data-desk-stuck]',()=>{const id=taskId(),t=source().tasks.find(t=>t.id===id),result=deskHelp(state,id,options);if(!result){status(failed,true);return;}const rung=view().steps[stepId()].help[id];redraw(rung===1?t.hint:rung===2?t.example:'Leave this question open. Your other work stays here.','#desk-status');});
 bind('[data-desk-leave]',()=>act(()=>setDeskLocation(state,null,null,options),'The question stays open; your other work stays here.'));
 bind('[data-desk-keep]',()=>{const id=taskId(),result=transact(candidate=>{const r=keepDeskTask(candidate,id);if(r&&id==='1d'&&['match','different'].includes(r.outcome)&&!addDeskSupport(candidate,'cost','cost-contrast','1d'))return false;return r;});if(result===false||result===null){status('Choose or enter an answer first. Check its format, or leave this question open.',true);return;}if(result.outcome==='uncheckable'){status(result.feedback,true);return;}redraw(result.feedback||'Your reading is kept.','#desk-status');});
 const write=(value,el)=>{const before=view().steps?.[stepId()]?.drafts?.[taskId()];if(setDeskDraft(state,taskId(),value,options)===false){if(el&&typeof before==='string')el.value=before;status(failed,true);return false;}save();return true;};
 root.querySelector('[data-desk-answer]')?.addEventListener('input',e=>{if(live(e.currentTarget))write(e.currentTarget.value,e.currentTarget);});
 root.querySelectorAll('[data-desk-budget]').forEach(el=>el.addEventListener('change',()=>{if(!live(el))return;const value={...(view().steps?.[stepId()]?.drafts?.[taskId()]||{})};value[el.dataset.deskBudget]=el.value;write(value);}));
 root.querySelectorAll('[data-desk-source-kind],[data-desk-source-card]').forEach(el=>el.addEventListener('change',()=>{if(!live(el))return;const old=view().steps?.[stepId()]?.drafts?.[taskId()]||{},value={kind:old.kind||'',cards:{...old.cards}};if(el.hasAttribute('data-desk-source-kind'))value.kind=el.value;else value.cards[el.dataset.deskSourceCard]=el.value;write(value);}));
 root.querySelectorAll('[data-desk-choice]').forEach(el=>el.addEventListener('change',()=>{if(!live(el))return;const t=source().tasks.find(t=>t.id===taskId());write(t.kind==='multi'?[...root.querySelectorAll('[data-desk-choice]:checked')].map(x=>x.dataset.deskChoice):el.dataset.deskChoice);}));
 bind('[data-desk-tile]',b=>{const input=root.querySelector('[data-desk-answer]');if(!input)return;const value=input.value+b.dataset.deskTile;if(value.length>160)return;if(addDeskSupport(state,stepId(),'tiles',taskId(),options)===false)return status(failed,true);if(write(value,input)){input.value=value;input.focus();}});
 bind('[data-desk-clear]',()=>{const input=root.querySelector('[data-desk-answer]');if(input&&write('',input)){input.value='';input.focus();}});
 root.querySelector('[data-desk-trials]')?.addEventListener('submit',e=>{e.preventDefault();if(!live(e.currentTarget))return;act(()=>addDeskTrial(state,Number(new FormData(e.currentTarget).get('length')),options),'This length is added to your trial table.');});
 root.querySelectorAll('[data-desk-reference],[data-desk-equation]').forEach(d=>d.addEventListener('toggle',()=>{if(d.dataset.deskRestoring){delete d.dataset.deskRestoring;return;}if(!d.open||!live(d)||!stepId())return;if(addDeskSupport(state,stepId(),d.hasAttribute('data-desk-equation')?'equation':'reference',taskId(),options)!==false)save();else{d.open=false;status(failed,true);}}));
 root.querySelectorAll('[data-desk-rec]').forEach(el=>el.addEventListener('input',()=>{if(!live(el))return;const before=view().record.recommendation.draft[el.dataset.deskRec];if(setDeskRecommendation(state,el.dataset.deskRec,el.value,{...options,objectionCode:el.dataset.deskObjectionCode})===false){el.value=before;status(failed,true);}else{save();const b=root.querySelector(`[data-desk-use-starter="${el.dataset.deskRec}"]`);if(b)b.textContent=el.value?'Replace my draft with this sentence':'Use this sentence';if(el.dataset.deskRec==='plan'){const p=root.querySelector('[data-desk-use-plan]');if(p)p.textContent=el.value?'Replace plan with selected words':'Use selected plan';}}}));
 bind('[data-desk-use-plan]',()=>{const el=root.querySelector('[data-desk-plan]'),p=source().recommendation.plans.find(p=>p.id===el.value);if(!p)return status('Choose a plan first.',true);act(()=>setDeskRecommendation(state,'plan',p.id==='custom'?view().recommendation.draft.plan:p.label,{...options,supplied:p.id!=='custom',planId:p.id}),'Selected plan ready to edit. Your earlier objection answer stays with its question.','[data-desk-plan]');});
 bind('[data-desk-use-starter]',b=>{const field=b.dataset.deskUseStarter,el=root.querySelector(`[data-desk-starter="${field}"]`),text=source().recommendation.starters[field]?.[Number(el.value)];if(el.value===''||!text)return status('Choose a sentence first.',true);act(()=>setDeskRecommendation(state,field,text,{...options,supplied:true}),'Sentence added. You can edit it.',`[data-desk-starter="${field}"]`);});
 bind('[data-desk-new-objection]',()=>act(()=>useDeskObjection(state,options),'The current draft now answers the new objection; kept pages stay unchanged.'));
 bind('[data-desk-keep-recommendation]',()=>{const result=keepDeskRecommendation(state,options);if(!result){status('Add a plan, reason, objection answer and uncertainty. Each part has ready-made sentences you can use.',true);return;}redraw('Your page is on the noticeboard. You can keep revising it.','.desk-recommendation');});
 bind('[data-desk-together]',()=>{if(stepId())act(()=>addDeskSupport(state,stepId(),'together',taskId(),options),'Thinking together is recorded for this part.');else status('Open a case part to record thinking together.');});
 root.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',e=>{if(!live(b)){e.preventDefault();e.stopImmediatePropagation();return;}if(stepId()&&addDeskSupport(state,stepId(),'audio',taskId(),options)===false){e.preventDefault();e.stopImmediatePropagation();status(failed,true);return;}if(stepId())save();b.dataset.speak=[...root.querySelectorAll('h1,h2,h3,p,blockquote,label,th,td')].filter(x=>x.getClientRects().length&&!x.closest('details:not([open])')).map(x=>x.textContent).join(' ');},{capture:true}));
}
